//----------------------------------------------------------------------------------------------------------------------------------
// build_id.c - the build identity as data: the commit hash and the commit time (build_time.h, generated by the Makefile from
// git or from PC_FW_BUILD / SOURCE_DATE_EPOCH). Code reads these objects instead of compiling the values in, so a different
// commit changes these 10 bytes and nothing else: the code size and the layout of the image do not depend on the identity.
// Linked last (Makefile SRCS) so even its own size cannot move anything.
//----------------------------------------------------------------------------------------------------------------------------------

#include <stdint.h>
#include "build_time.h"

const uint32_t pc_fw_build = PC_FW_BUILD;
const uint8_t  pc_build_time[6] = { COMPILE_YEAR, COMPILE_MONTH, COMPILE_DAY, COMPILE_HOUR, COMPILE_MIN, COMPILE_SEC };
